smart.css:
.smc-root {
  color: var(--smc-text);
  font-family: var(--smc-font-body);
  font-size: 17px;
  line-height: 1.75;
}

.smc-root h2,
.smc-root h3 {
  color: var(--smc-primary);
  font-family: var(--smc-font-heading);
}

.smc-root h2 {
  margin: 38px 0 16px;
  padding: 13px 16px;
  border-left: 5px solid var(--smc-accent);
  border-radius: 0 var(--smc-radius) var(--smc-radius) 0;
  background: color-mix(in srgb, var(--smc-surface) 86%, var(--smc-accent) 14%);
  font-size: clamp(25px, 4vw, 34px);
  line-height: 1.25;
}

.smc-root h2:first-child {
  margin-top: 0;
}

.smc-root h3 {
  margin: 28px 0 10px;
  padding: 0 0 8px;
  border-bottom: 1px solid var(--smc-border);
  font-size: clamp(20px, 3vw, 25px);
  line-height: 1.35;
}

.smc-root p {
  margin: 0 0 15px;
}

.smc-root strong {
  color: var(--smc-primary);
  font-weight: 700;
}

.smc-root a {
  color: var(--smc-accent);
  font-weight: 650;
  text-decoration: underline;
  text-decoration-thickness: 1px;
  text-underline-offset: 3px;
}

.smc-root a:hover {
  color: var(--smc-primary);
}

.smc-root table {
  display: table;
  width: 100%;
  margin: 20px 0 28px;
  overflow: hidden;
  border: 1px solid var(--smc-border);
  border-collapse: separate;
  border-spacing: 0;
  border-radius: var(--smc-radius);
  background: var(--smc-bg);
}

.smc-root th,
.smc-root td {
  padding: 13px 14px;
  border-right: 1px solid var(--smc-border);
  border-bottom: 1px solid var(--smc-border);
  text-align: left;
  vertical-align: top;
}

.smc-root th {
  color: var(--smc-bg);
  background: var(--smc-primary);
  font-family: var(--smc-font-heading);
  font-weight: 700;
}

.smc-root tr:last-child td {
  border-bottom: 0;
}

.smc-root th:last-child,
.smc-root td:last-child {
  border-right: 0;
}

.smc-root tbody tr:nth-child(even) td {
  background: var(--smc-surface);
}

.smc-root ul,
.smc-root ol {
  margin: 16px 0 24px;
  padding-left: 26px;
}

.smc-root li {
  margin: 0 0 10px;
  padding-left: 5px;
}

.smc-root ol li::marker {
  color: var(--smc-accent);
  font-weight: 800;
}

.smc-root ul li::marker {
  color: var(--smc-primary);
}

.smc-root h2:nth-last-of-type(2) + ul {
  padding: 18px 20px 12px 42px;
  border: 1px solid var(--smc-border);
  border-radius: var(--smc-radius);
  background: var(--smc-surface);
}

@container smc (max-width: 620px) {
  .smc-root {
    font-size: 16px;
    line-height: 1.7;
  }

  .smc-root h2 {
    margin-top: 30px;
    padding: 11px 13px;
  }

  .smc-root h3 {
    margin-top: 24px;
  }

  .smc-root table {
    display: block;
    overflow-x: auto;
    border-radius: var(--smc-radius);
    -webkit-overflow-scrolling: touch;
  }

  .smc-root table thead,
  .smc-root table tbody {
    min-width: 620px;
  }

  .smc-root th,
  .smc-root td {
    min-width: 180px;
    padding: 11px 12px;
  }
}

